    42	function useOptions({isGroupChat}: NewChatPageProps) {
    43	    const [searchTerm, debouncedSearchTerm, setSearchTerm] = useDebouncedState('');
    44	    const [selectedOptions, setSelectedOptions] = useState<Array<ListItem & OptionData>>([]);
    45	    const [betas] = useOnyx(ONYXKEYS.BETAS);
    46	    const [newGroupDraft] = useOnyx(ONYXKEYS.NEW_GROUP_CHAT_DRAFT);
