    48	    const {didScreenTransitionEnd} = useScreenWrapperTranstionStatus();
    49	    const {options: listOptions, areOptionsInitialized} = useOptionsList({
    50	        shouldInitialize: didScreenTransitionEnd,
    51	    });
    52	
    53	    const defaultOptions = useMemo(() => {
    54	        const filteredOptions = OptionsListUtils.getFilteredOptions(
    55	            listOptions.reports ?? [],
    56	            listOptions.personalDetails ?? [],
    57	            betas ?? [],
    58	            '',
    59	            selectedOptions,
    60	            isGroupChat ? excludedGroupEmails : [],
