    69	            true,
    70	            undefined,
    71	            undefined,
    72	            0,
    73	            undefined,
    74	            true,
    75	        );
    76	        return filteredOptions;
    77	    }, [betas, isGroupChat, listOptions.personalDetails, listOptions.reports, selectedOptions]);
