    79	    const options = useMemo(() => {
    80	        const filteredOptions = OptionsListUtils.filterOptions(defaultOptions, debouncedSearchTerm, {
    81	            selectedOptions,
    82	            excludeLogins: isGroupChat ? excludedGroupEmails : [],
    83	            maxRecentReportsToShow: CONST.IOU.MAX_RECENT_REPORTS_TO_SHOW,
    84	        });
    85	
    86	        return filteredOptions;
    87	    }, [debouncedSearchTerm, defaultOptions, isGroupChat, selectedOptions]);
    88	    const cleanSearchTerm = useMemo(() => debouncedSearchTerm.trim().toLowerCase(), [debouncedSearchTerm]);
    89	    const headerMessage = useMemo(() => {
    90	        return OptionsListUtils.getHeaderMessage(
    91	            options.personalDetails.length + options.recentReports.length !== 0,
    92	            !!options.userToInvite,
    93	            debouncedSearchTerm.trim(),
    94	            selectedOptions.some((participant) => OptionsListUtils.getPersonalDetailSearchTerms(participant).join(' ').toLowerCase?.().includes(cleanSearchTerm)),
    95	        );
    96	    }, [cleanSearchTerm, debouncedSearchTerm, options.personalDetails.length, options.recentReports.length, options.userToInvite, selectedOptions]);
    97	
    98	    useEffect(() => {
    99	        if (!debouncedSearchTerm.length) {
   100	            return;
   101	        }
   102	
   103	        Report.searchInServer(debouncedSearchTerm);
   104	    }, [debouncedSearchTerm]);
   105	
   106	    useEffect(() => {
   107	        if (!newGroupDraft?.participants) {
   108	            return;
   109	        }
   110	        const newSelectedOptions: OptionData[] = [];
   111	        newGroupDraft.participants.forEach((participant) => {
   112	            if (participant.accountID === personalData.accountID) {
   113	                return;
